_CUDA = r"""
#include <torch/extension.h>

#include <c10/cuda/CUDAGuard.h>
#include <cusolverDn.h>
#include <cub/warp/warp_merge_sort.cuh>

#include <cstdint>
#include <vector>

#define CUSOLVER_CHECK(expr)                                                   \
  do {                                                                         \
    const cusolverStatus_t status = (expr);                                    \
    TORCH_CHECK(status == CUSOLVER_STATUS_SUCCESS, #expr,                      \
                " failed with cuSOLVER status ", static_cast<int>(status));   \
  } while (0)

namespace {

struct FloatLess {
  __device__ bool operator()(float left, float right) const {
    return left < right;
  }
};

__global__ void sort_eigenpairs32(float* vectors, float* values) {
  using WarpSort = cub::WarpMergeSort<float, 1, 32, int>;
  __shared__ typename WarpSort::TempStorage sort_storage;
  __shared__ int permutation[32];
  __shared__ float matrix_copy[32 * 32];

  const int tid = static_cast<int>(threadIdx.x);
  float* matrix = vectors + static_cast<int64_t>(blockIdx.x) * 32 * 32;
  float* eigenvalues = values + static_cast<int64_t>(blockIdx.x) * 32;

  if (tid < 32) {
    float keys[1] = {eigenvalues[tid]};
    int columns[1] = {tid};
    WarpSort(sort_storage).Sort(keys, columns, FloatLess{});
    eigenvalues[tid] = keys[0];
    permutation[tid] = columns[0];
  }
  for (int index = tid; index < 32 * 32; index += blockDim.x) {
    matrix_copy[index] = matrix[index];
  }
  __syncthreads();
  for (int index = tid; index < 32 * 32; index += blockDim.x) {
    const int row = index & 31;
    const int destination_column = index >> 5;
    matrix[index] = matrix_copy[permutation[destination_column] * 32 + row];
  }
}

struct SolverState {
  cusolverDnHandle_t handle = nullptr;
  cusolverDnParams_t params = nullptr;
  int64_t n = -1;
  int64_t batch = -1;
  size_t device_bytes = 0;
  size_t host_bytes = 0;
  torch::Tensor device_workspace;
  torch::Tensor info;
  std::vector<unsigned char> host_workspace;

  SolverState() {
    CUSOLVER_CHECK(cusolverDnCreate(&handle));
    CUSOLVER_CHECK(cusolverDnCreateParams(&params));
  }

  ~SolverState() {
    if (params != nullptr) {
      cusolverDnDestroyParams(params);
    }
    if (handle != nullptr) {
      cusolverDnDestroy(handle);
    }
  }
};

SolverState& state() {
  static SolverState instance;
  return instance;
}

struct JacobiState {
  cusolverDnHandle_t handle = nullptr;
  syevjInfo_t params = nullptr;
  int64_t n = -1;
  int64_t batch = -1;
  int lwork = 0;
  double tolerance = -1.0;
  int max_sweeps = -1;
  torch::Tensor workspace;
  torch::Tensor info;

  JacobiState() {
    CUSOLVER_CHECK(cusolverDnCreate(&handle));
    CUSOLVER_CHECK(cusolverDnCreateSyevjInfo(&params));
    CUSOLVER_CHECK(cusolverDnXsyevjSetSortEig(params, 0));
  }

