      cusolverDnDestroySyevjInfo(params);
    }
    if (handle != nullptr) {
      cusolverDnDestroy(handle);
    }
  }
};

JacobiState& jacobi_state() {
  static JacobiState instance;
  return instance;
}

}  // namespace

std::vector<torch::Tensor> xsyev_batched(torch::Tensor input) {
  TORCH_CHECK(input.is_cuda(), "input must be a CUDA tensor");
  TORCH_CHECK(input.scalar_type() == torch::kFloat32, "input must be FP32");
  TORCH_CHECK(input.dim() == 3 && input.size(1) == input.size(2),
              "input must have shape [batch, n, n]");

  const c10::cuda::CUDAGuard device_guard(input.device());
  const int64_t batch = input.size(0);
  const int64_t n = input.size(1);
  const cublasFillMode_t uplo =
      n >= 2048 ? CUBLAS_FILL_MODE_UPPER : CUBLAS_FILL_MODE_LOWER;
  auto vectors_col_major = input.contiguous().clone();
  auto values = torch::empty({batch, n}, input.options());

  SolverState& s = state();

  if (s.n != n || s.batch != batch) {
#if defined(CUDART_VERSION) && CUDART_VERSION >= 13030 && \
    !defined(EIGH_DISABLE_BF16X9)
    const cusolverMathMode_t math_mode =
        n >= 512 ? CUSOLVER_FP32_EMULATED_BF16X9_MATH
                  : CUSOLVER_DEFAULT_MATH;
    CUSOLVER_CHECK(cusolverDnSetMathMode(s.handle, math_mode));
#endif
    size_t device_bytes = 0;
    size_t host_bytes = 0;
    CUSOLVER_CHECK(cusolverDnXsyevBatched_bufferSize(
        s.handle, s.params, CUSOLVER_EIG_MODE_VECTOR, uplo, n, CUDA_R_32F,
        vectors_col_major.data_ptr<float>(), n, CUDA_R_32F,
        values.data_ptr<float>(), CUDA_R_32F, &device_bytes, &host_bytes,
        batch));

    s.n = n;
    s.batch = batch;
    s.device_bytes = device_bytes;
    s.host_bytes = host_bytes;
    s.device_workspace = torch::empty(
        {static_cast<int64_t>(device_bytes)},
        input.options().dtype(torch::kUInt8));
    s.info = torch::empty(
        {batch}, input.options().dtype(torch::kInt32));
    s.host_workspace.resize(host_bytes);
  }

  CUSOLVER_CHECK(cusolverDnXsyevBatched(
      s.handle, s.params, CUSOLVER_EIG_MODE_VECTOR, uplo, n, CUDA_R_32F,
      vectors_col_major.data_ptr<float>(), n, CUDA_R_32F,
      values.data_ptr<float>(), CUDA_R_32F,
      s.device_bytes == 0 ? nullptr : s.device_workspace.data_ptr(),
      s.device_bytes,
      s.host_bytes == 0 ? nullptr : s.host_workspace.data(), s.host_bytes,
      s.info.data_ptr<int>(), batch));

  // cuSOLVER writes column-major eigenvectors into row-major storage.
  return {vectors_col_major.transpose(1, 2), values};
}

std::vector<torch::Tensor> syevj_batched(
    torch::Tensor input, double tolerance, int64_t max_sweeps) {
  TORCH_CHECK(input.is_cuda(), "input must be a CUDA tensor");
  TORCH_CHECK(input.scalar_type() == torch::kFloat32, "input must be FP32");
  TORCH_CHECK(input.dim() == 3 && input.size(1) == input.size(2),
              "input must have shape [batch, n, n]");

  const c10::cuda::CUDAGuard device_guard(input.device());
  const int batch = static_cast<int>(input.size(0));
  const int n = static_cast<int>(input.size(1));
  auto vectors_col_major = input.contiguous().clone();
  auto values = torch::empty({batch, n}, input.options());

  JacobiState& s = jacobi_state();
  if (s.tolerance != tolerance || s.max_sweeps != max_sweeps) {
    CUSOLVER_CHECK(cusolverDnXsyevjSetTolerance(s.params, tolerance));
    CUSOLVER_CHECK(cusolverDnXsyevjSetMaxSweeps(
        s.params, static_cast<int>(max_sweeps)));
    s.tolerance = tolerance;
    s.max_sweeps = static_cast<int>(max_sweeps);
  }
  if (s.n != n || s.batch != batch) {
    int lwork = 0;
    CUSOLVER_CHECK(cusolverDnSsyevjBatched_bufferSize(
        s.handle, CUSOLVER_EIG_MODE_VECTOR, CUBLAS_FILL_MODE_LOWER, n,
        vectors_col_major.data_ptr<float>(), n, values.data_ptr<float>(),
        &lwork, s.params, batch));
    s.n = n;
    s.batch = batch;
    s.lwork = lwork;
    s.workspace = torch::empty({lwork}, input.options());
    s.info = torch::empty(
        {batch}, input.options().dtype(torch::kInt32));
  }

  CUSOLVER_CHECK(cusolverDnSsyevjBatched(
      s.handle, CUSOLVER_EIG_MODE_VECTOR, CUBLAS_FILL_MODE_LOWER, n,
      vectors_col_major.data_ptr<float>(), n, values.data_ptr<float>(),
      s.workspace.data_ptr<float>(), s.lwork, s.info.data_ptr<int>(), s.params,
      batch));
  sort_eigenpairs32<<<batch, 128>>>(
      vectors_col_major.data_ptr<float>(), values.data_ptr<float>());
  return {vectors_col_major.transpose(1, 2), values};
}
